using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "MirrorOfThoughtOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/MirrorOfThought Omen Data")]
public class MirrorOfThoughtOmenData : OmenData
{
	[Header("Freeze Debt Omen")]
	[SerializeField]
	private StarAbilityReference starAbilityReference;

	[SerializeField]
	private KarmicOrbStarAbility KarmicOrbStarAbility;

	[SerializeField]
	private PenitenceBurstEffect penitenceBurstEffect;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.MirrorOfThoughtOmenAction = delegate
		{
			if (starAbilityReference.Value == KarmicOrbStarAbility)
			{
				ActivateOmen();
			}
		};
		ReferenceSingleton<OrionOmensHandler>.Instance.OnDeactivatingKarmicOrbMirrorOfThoughtOmenAction = delegate
		{
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().RemoveEffect(penitenceBurstEffect);
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.MirrorOfThoughtOmenAction = null;
		ReferenceSingleton<OrionOmensHandler>.Instance.OnDeactivatingKarmicOrbMirrorOfThoughtOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		string arg = base.OmenConvertedDescription();
		return Smart.Format(GetOmenRawLocalizedDescription(), arg, base.localizationManager.GetLocalizedLoseAllEffect(penitenceBurstEffect).LowercaseFirst());
	}
}
